import { Component, Emit, Prop, Vue } from 'vue-property-decorator';
import { OverlaysEventEmitter } from '../../event-emitter';
import { ISessionAlertsTranslations } from '../../translations';

export type SessionAlertType = 'ten-minute-warning' | 'immediate-logout' | 'session-notification';

interface IAlertData {
    title: string;
    body: string;
    continueButton: string;
    smallPrint?: string;
    timeSpentLabel?: string;
    timeSpentValue?: string;
    moneySpentLabel?: string;
    moneySpentValue?: string;
}

@Component({
    name: 'SessionAlerts'
})
export default class SessionAlerts extends Vue {
    @Prop({
        required: false,
        type: Object,
        default() {
            return {
                tenMinuteWarning: {
                    title: '10 Minute Warning',
                    body: 'You will be logged out in 10 minutes',
                    continueButton: 'Continue'
                },
                immediateLogout: {
                    title: 'Session Timeout',
                    body: 'Your session has expired',
                    smallPrint: 'Please log in again to continue',
                    continueButton: 'OK'
                },
                sessionNotification: {
                    title: 'Session Summary',
                    body: 'Here is your current session information',
                    timeSpentLabel: 'Time Spent',
                    moneySpentLabel: 'Money Spent',
                    smallPrint: 'Remember to play responsibly',
                    continueButton: 'Continue'
                },
                closeButton: 'Close'
            };
        }
    })
    public translations: ISessionAlertsTranslations;

    public isVisible: boolean = false;
    public alertType: SessionAlertType = 'ten-minute-warning';
    public alertData: IAlertData | null = null;

    public created() {
        this.showTenMinuteWarning = this.showTenMinuteWarning.bind(this);
        this.showImmediateLogout = this.showImmediateLogout.bind(this);
        this.showSessionNotification = this.showSessionNotification.bind(this);
        this.hide = this.hide.bind(this);
    }

    public mounted() {
        OverlaysEventEmitter.on('showTenMinuteWarning', this.showTenMinuteWarning, this);
        OverlaysEventEmitter.on('showImmediateLogout', this.showImmediateLogout, this);
        OverlaysEventEmitter.on('showSessionNotification', this.showSessionNotification, this);
    }

    public beforeDestroy() {
        OverlaysEventEmitter.off('showTenMinuteWarning', this.showTenMinuteWarning, this);
        OverlaysEventEmitter.off('showImmediateLogout', this.showImmediateLogout, this);
        OverlaysEventEmitter.off('showSessionNotification', this.showSessionNotification, this);
    }

    public showTenMinuteWarning(data: { title: string; body: string; continueButton: string }) {
        this.alertType = 'ten-minute-warning';
        this.alertData = {
            title: data.title,
            body: data.body,
            continueButton: data.continueButton
        };
        this.show();
    }

    public showImmediateLogout(data: { title: string; body: string; smallPrint: string; continueButton: string }) {
        this.alertType = 'immediate-logout';
        this.alertData = {
            title: data.title,
            body: data.body,
            smallPrint: data.smallPrint,
            continueButton: data.continueButton
        };
        this.show();
    }

    public showSessionNotification(data: { 
        title: string; 
        body: string; 
        timeSpentLabel: string; 
        timeSpentValue: string; 
        moneySpentLabel: string; 
        moneySpentValue: string; 
        smallPrint: string; 
        continueButton: string 
    }) {
        this.alertType = 'session-notification';
        this.alertData = {
            title: data.title,
            body: data.body,
            timeSpentLabel: data.timeSpentLabel,
            timeSpentValue: data.timeSpentValue,
            moneySpentLabel: data.moneySpentLabel,
            moneySpentValue: data.moneySpentValue,
            smallPrint: data.smallPrint,
            continueButton: data.continueButton
        };
        this.show();
    }

    private show() {
        this.isVisible = true;
    }

    private hide() {
        this.isVisible = false;
        this.alertData = null;
    }

    @Emit('onClose')
    public onCloseClick() {
        this.hide();
        return this.alertType;
    }

    @Emit('onContinue')
    public onContinueClick() {
        this.hide();
        return this.alertType;
    }
}
